import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const root = new Group();
  root.name = 'brand-mark-wall';

  const COLORS = {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    rampTop: '#1a1a22',
    rampBottom: '#121218',
  };

  const timelines = [];
  const disposables = [];
  const materials = [];

  // ---- Backdrop stage plane (vertical gradient) ----
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const t = uv().y;
    bgMat.colorNode = mix(color(COLORS.rampBottom), color(COLORS.rampTop), t);
  }
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  root.add(bg);
  disposables.push(bgGeo, bgMat);

  // ---- Lighting (node-local rim/key; ambient/key provided by scene too) ----
  const ambient = new AmbientLight(0xffffff, 0.5);
  root.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.2);
  // 35deg elevation raking from the left
  key.position.set(-3, 2.1, 4);
  root.add(key);

  const rim = new DirectionalLight(new Color(COLORS.accent), 0.7);
  rim.position.set(3.5, -1.5, 2.5);
  root.add(rim);

  // ---- Text items handling (robust against non‑array payloads) ----
  const rawItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const itemsArray = Array.isArray(rawItems) ? rawItems : [];
  const defaultItems = [
    { text: 'AS FEATURED IN', role: 'kicker' },
    { text: 'HODINKEE', role: 'brand-mark' },
    { text: 'MONOCLE', role: 'brand-mark' },
    { text: 'WALLPAPER', role: 'brand-mark' },
    { text: 'ESQUIRE', role: 'brand-mark' },
    { text: 'WIRED', role: 'brand-mark' },
    { text: 'FINANCIAL TIMES', role: 'brand-mark' },
  ];
  const textItems = itemsArray.length ? itemsArray : defaultItems;

  const kicker = textItems.find((i) => i.role === 'kicker');
  const brandMarks = textItems.filter((i) => i.role === 'brand-mark');

  // grid geometry constants
  const TILE_W = 1.0;
  const TILE_H = 0.62;
  const GAP = 0.25;
  const COLS = 3;
  const ROWS = 2;
  const gridW = COLS * TILE_W + (COLS - 1) * GAP;
  const gridH = ROWS * TILE_H + (ROWS - 1) * GAP;

  if (kicker) {
    const kt = ctx.fontAtlas.createText(kicker.text, {
      fontSize: 38,
      color: COLORS.accent,
      align: 'center',
      letterSpacingPx: 6,
    });
    kt.position.set(0, gridH / 2 + 0.3, 0.05);
    root.add(kt);
  }

  // tile albedo ramp material factory
  function makeTileMaterial() {
    const mat = new MeshStandardNodeMaterial();
    const t = uv().y;
    mat.colorNode = mix(color(COLORS.rampBottom), color(COLORS.rampTop), t);
    mat.roughness = 0.55;
    mat.metalness = 0.5;
    mat.clearcoat = 0.2;
    materials.push(mat);
    disposables.push(mat);
    return mat;
  }

  const tileGeo = new BoxGeometry(TILE_W, TILE_H, 0.04);
  disposables.push(tileGeo);

  const tiles = [];
  const handlers = {};

  // order top row left-to-right first
  const order = [];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      order.push({ r, c, index: r * COLS + c });
    }
  }

  order.forEach(({ r, c, index }) => {
    const brand = brandMarks[index];
    if (!brand) return;

    const tileGroup = new Group();
    tileGroup.name = `tile-${index}`;

    const x = -gridW / 2 + TILE_W / 2 + c * (TILE_W + GAP);
    const y = gridH / 2 - TILE_H / 2 - r * (TILE_H + GAP);
    tileGroup.position.set(x, y, 0);

    const tileMesh = new Mesh(tileGeo, makeTileMaterial());
    tileGroup.add(tileMesh);

    // wordmark
    const label = ctx.fontAtlas.createText(brand.text, {
      fontSize: 44,
      color: COLORS.paper,
      align: 'center',
      letterSpacingPx: 3,
      maxWidthPx: 300,
    });
    label.position.set(0, 0, 0.03);
    if (label.traverse) {
      label.traverse((o) => {
        if (o.material) {
          o.material.transparent = true;
          o.material.opacity = 0.78;
        }
      });
    }
    tileGroup.add(label);

    // mount entrance state
    tileGroup.position.y = y + 0.2;
    if (tileMesh.material) {
      tileMesh.material.transparent = true;
      tileMesh.material.opacity = 0;
    }

    root.add(tileGroup);
    tiles.push({ group: tileGroup, mesh: tileMesh, label, restY: y });
  });

  // ---- Mount animation: stagger-cards fade-up ----
  const mountTl = gsap.timeline();
  tiles.forEach((t, i) => {
    mountTl.to(
      t.group.position,
      { y: t.restY, duration: 0.5, ease: 'power2.out' },
      i * 0.08,
    );
    if (t.mesh.material) {
      mountTl.to(
        t.mesh.material,
        { opacity: 1, duration: 0.5, ease: 'power2.out' },
        i * 0.08,
      );
    }
  });
  timelines.push(mountTl);

  // idle subtle breathing on key light to sweep anisotropic highlight
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(key.position, { x: -2, duration: 6, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---- Hover handlers ----
  function setTileHover(tile, hovered) {
    gsap.to(tile.group.position, {
      z: hovered ? 0.05 : 0,
      duration: 0.16,
      ease: 'power2.out',
    });
    if (tile.label && tile.label.traverse) {
      tile.label.traverse((o) => {
        if (o.material) {
          gsap.to(o.material, {
            opacity: hovered ? 1.0 : 0.78,
            duration: 0.16,
            ease: 'power2.out',
          });
        }
      });
    }
  }

  handlers.hover = (payload) => {
    const obj = payload && payload.object;
    if (!obj) return;
    tiles.forEach((tile) => {
      let match = false;
      tile.group.traverse((o) => {
        if (o === obj) match = true;
      });
      setTileHover(tile, match);
    });
  };

  handlers.hoverend = () => {
    tiles.forEach((tile) => setTileHover(tile, false));
  };

  root.userData.handlers = handlers;

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill());
    tiles.forEach((tile) => {
      gsap.killTweensOf(tile.group.position);
    });
    disposables.forEach((d) => d && d.dispose && d.dispose());
  };

  return root;
}
